  const ex = (gx - LAKE.x) / LAKE.rx, ey = (gy - LAKE.y) / LAKE.ry, ang = Math.atan2(ey, ex);
  const r = 1 + 0.12 * Math.sin(3 * ang + 1) + 0.07 * Math.sin(5 * ang + 2);
