  p.act = act; p.goal = null; p.loiter = false; p.legs = 0;
  if (place) { p.x = place.x; p.y = place.y; p.inside = place; p.hidden = true; p.wait = 3 + Math.random() * 15; }
  else { p.x = p.home.x; p.y = p.home.y; p.inside = null; p.hidden = false; p.wait = 0; }
