const taskBuy = (ven, id) => !!task && task.kind === 'fetch' && ven.type === task.type && id === task.want;
// E on the lost dog
const nearDog = () => task && task.kind === 'dog' && !task.dog.follow && Math.hypot(rel(task.dog.x - px), rel(task.dog.y - py)) < 0.5;

