  if (kind === 'gardens' && inGardens(x, y)) { const [gx, gy] = gardenLocal(x, y); return onJetty(gx, gy) ? 'wood' : gardenPathDist(gx, gy) < 0.25 ? 'gravel' : 'grass'; }
  if (kind === 'park') return inPond(mod(x, 8), mod(y, 8), bx & (NB - 1), by & (NB - 1), 0.15) ? 'wood' : 'grass';
