    if (fd > 0.36 && fd < 0.64 && z < 0.24) return set(i, fd < 0.38 || fd > 0.62 ? '|' : z > 0.2 ? '=' : '#', C(GRAY, L * 0.8)); // the doors
    if (z > 0.08 && z < 0.22 && (fd < 0.26 || fd > 0.74)) return set(i, ':', C(CYAN, lit * 0.75));
