    if (hash(Math.floor(u * 5), fl, sk) > litT - 0.35) { BG[i] = C(CYAN, 1 + night * 2.5); return set(i, '-', C(WHITE, Math.max(L * 0.8, glowL))); } // wards lit all night
    return set(i, ' ', 0);
