      set(i, step > 0 ? '\\' : step < 0 ? '/' : '|', C(WHITE, 15)); BG[i] = C(CYAN, 5 + fl * 6); FOGS[i] = 0;
      if (r === fork && !k) branch(c, r + 1, Math.min(bot, r + (bot - top) * 0.35), hash(bolt.seed, 3, 7) < 0.5 ? -1 : 1);
