const STREET_TAGS = ['KAT', 'REX', 'ZEN', 'MOE', 'DUKE', 'JINX', 'NOX', 'VEX', 'SKY', 'BOO', 'ACE', 'OZ', 'RAZE', 'FLY'];
const TAG_FLOURISH = ['^^^', '~~~', '->', '*', '!!', '<3', '==='];
