const TAG_WORDS = ['ACE', 'ZAP', 'YO', 'KAT', 'REX', 'OK', 'WOW', 'RAD', 'BAM', 'HEY', 'GO', 'ART'];
const designCount = TAG_ART.length + TAG_WORDS.length;

