      s.u = run.u0 + 0.15 + span * (0.5 + 0.45 * Math.sin(T * 0.07 + s.ph * 6.28));
      s.z = s.lo + (s.hi - s.lo) * (0.5 + 0.5 * Math.sin(T * 0.12 + s.wob)); s.dir = 1;
      continue;
