    s.u = run.u0 + 0.15 + (there ? p : 2 * span - p) + s.off; s.dir = there ? 1 : -1;
    s.z = clamp(s.lo + (s.hi - s.lo) * s.zf + s.offz + 0.06 * Math.sin(T * 0.6 + s.wob), s.lo, s.hi);
