    const vx = rel(wx - px), vy = rel(wy - py), depth = dx * vx + dy * vy;
    if (depth < 1) return;
    const c = Math.round(cols / 2 + (-dy * vx + dx * vy) * projX / depth), r = Math.round(hor - (wz - eye) * projY / depth);
    if (c < 0 || c >= cols || r < 0 || r >= rows) return;
