  if (mode === 'sea' && sea) { sea.v = 0; if (sea.hired) { sea.hired = false; const s = SLOTS[sea.slot]; Object.assign(sea, { x: s.x, y: s.y, hx: s.hx, hy: s.hy }); } sea = null; }
