    const object = peeObjectHit(ox, oy, oz, p.x, p.y, p.z), hit = wall && (!object || wall.t < object.t) ? wall : object;
    if (hit) { if (!p.splash) { peeMarkHit(hit, p); peeSplash(hit, p); } peeDrops.splice(k, 1); continue; }
