function gameFS(g) {
  const [cr, cb] = gameClear(), ratio = cw / FS; // (a character's width per px of height, in this font)
  return clamp(Math.floor(Math.min(DETAIL[settings.detail], (innerWidth - cr) / ((2 * g.W + 6) * ratio), (innerHeight - cb) / (g.H + 9))), 5, 40);
}
